package ai.decisionos.aside;
import android.content.*;import android.database.Cursor;import java.time.*;import java.time.format.*;import java.util.*;
/** Explicit ICS import preserves dates/timezones and UID, rejects unsupported recurrence rather than guessing. */
final class CampusCalendar {
 static final class Event {String uid,title,url="";String start,end,zone="Asia/Seoul";boolean all;}
 static List<Event> parse(String input){if(input.length()>250000||!input.contains("BEGIN:VCALENDAR"))throw new IllegalArgumentException("ICS 형식을 확인해 주세요.");List<Event> out=new ArrayList<>();Event e=null;String clean=input.replace("\r\n", "\n").replace("\n ", "").replace("\n\t", "");for(String line:clean.split("\n")){if(line.equals("BEGIN:VEVENT")){if(e!=null)throw new IllegalArgumentException();e=new Event();continue;}if(line.equals("END:VEVENT")){if(e==null||e.uid==null||e.title==null||e.start==null)throw new IllegalArgumentException("UID·제목·시작 시간이 필요해요.");if(e.all){LocalDate.parse(e.start);if(e.end==null)e.end=LocalDate.parse(e.start).plusDays(1).toString();if(!LocalDate.parse(e.end).isAfter(LocalDate.parse(e.start)))throw new IllegalArgumentException();}else{if(e.end==null)throw new IllegalArgumentException("종료 시간이 필요해요.");TaskEditor.values(e.title,"",false,e.start,e.end,e.zone);}out.add(e);e=null;continue;}if(e==null)continue;int c=line.indexOf(':');if(c<0)continue;String key=line.substring(0,c),value=line.substring(c+1);if(key.equals("RRULE")||key.equals("RDATE")||key.equals("EXDATE"))throw new IllegalArgumentException("반복 일정은 개별 일정으로 내보내 주세요.");if(key.equals("UID"))e.uid=value;if(key.equals("SUMMARY"))e.title=value.replace("\\n","\n").replace("\\,",",");if(key.equals("URL"))e.url=value;if(key.startsWith("DTSTART")||key.startsWith("DTEND")){boolean start=key.startsWith("DTSTART");boolean all=key.contains("VALUE=DATE")||value.matches("[0-9]{8}");String parsed;if(all){parsed=LocalDate.parse(value,DateTimeFormatter.BASIC_ISO_DATE).toString();}else{String zone="Asia/Seoul";if(key.contains("TZID="))zone=key.substring(key.indexOf("TZID=")+5).split(";")[0];ZoneId tz=ZoneId.of(zone);if(value.endsWith("Z")){parsed=LocalDateTime.ofInstant(Instant.from(DateTimeFormatter.ofPattern("yyyyMMdd'T'HHmmssX").withZone(ZoneOffset.UTC).parse(value)),ZoneId.of("Asia/Seoul")).toString();zone="Asia/Seoul";}else{parsed=LocalDateTime.parse(value,DateTimeFormatter.ofPattern("yyyyMMdd'T'HHmmss")).toString();}if(start)e.zone=zone;else if(!zone.equals(e.zone))throw new IllegalArgumentException("시작·종료 시간대가 달라요.");}if(start){e.start=parsed;e.all=all;}else{if(e.start!=null&&all!=e.all)throw new IllegalArgumentException();e.end=parsed;}}}if(e!=null||out.isEmpty())throw new IllegalArgumentException("가져올 일정이 없어요.");return out;}
 static int save(Context c,List<Event> events){try(TaskStore tasks=new TaskStore(c)){android.database.sqlite.SQLiteDatabase db=tasks.getWritableDatabase();db.beginTransaction();int count=0;try{for(Event e:events){String source="nubi-ics:"+CampusNoticeMonitor.hash(e.uid);try(Cursor row=db.rawQuery("SELECT _id FROM tasks WHERE source_url=?",new String[]{source})){if(row.moveToFirst())continue;}ContentValues v=TaskEditor.values(e.title,e.all?e.start:"",e.all,e.all?"":e.start,e.all?"":e.end,e.zone);v.put("kind","학교 ICS 일정");v.put("state","대기");v.put("source_url",source);db.insertOrThrow("tasks",null,v);count++;}db.setTransactionSuccessful();return count;}finally{db.endTransaction();}}}
}
